-- 003: Ingredients, finished goods, recipes, and an auditable stock ledger.
-- Run after 002. Stock deductions are called inside the payment transaction in 004.
begin;

create table if not exists public."InventoryItem" (
  "InventoryItemID" bigint generated by default as identity primary key,
  "Name" text not null,
  "ItemType" text not null check ("ItemType" in ('ingredient', 'finished_good')),
  "Unit" text not null,
  "QuantityOnHand" numeric(14,3) not null default 0 check ("QuantityOnHand" >= 0),
  "ReorderThreshold" numeric(14,3) not null default 0 check ("ReorderThreshold" >= 0),
  "IsActive" boolean not null default true,
  "CreatedAt" timestamptz not null default now(),
  "UpdatedAt" timestamptz not null default now()
);

create table if not exists public."MenuItemIngredient" (
  "MenuItemID" bigint not null references public."MenuItems"("ItemID") on delete restrict,
  "InventoryItemID" bigint not null references public."InventoryItem"("InventoryItemID") on delete restrict,
  "QuantityRequired" numeric(14,3) not null check ("QuantityRequired" > 0),
  primary key ("MenuItemID", "InventoryItemID")
);

create table if not exists public."InventoryMovement" (
  "InventoryMovementID" bigint generated by default as identity primary key,
  "InventoryItemID" bigint not null references public."InventoryItem"("InventoryItemID") on delete restrict,
  "QuantityChange" numeric(14,3) not null check ("QuantityChange" <> 0),
  "Reason" text not null,
  "MovementType" text not null check ("MovementType" in ('opening_balance', 'receipt', 'sale', 'waste', 'adjustment', 'return')),
  "OrderID" bigint,
  "EmployeeID" bigint,
  "CreatedAt" timestamptz not null default now()
);

create table if not exists public."OrderStockDeduction" (
  "OrderID" bigint primary key,
  "CreatedAt" timestamptz not null default now()
);

create index if not exists inventory_low_stock_idx
  on public."InventoryItem" ("QuantityOnHand", "ReorderThreshold") where "IsActive";
create index if not exists inventory_movement_item_date_idx
  on public."InventoryMovement" ("InventoryItemID", "CreatedAt" desc);

create or replace function public.esmiringkape_deduct_order_stock(p_order_id bigint, p_employee_id bigint)
returns void
language plpgsql
security definer
set search_path = pg_catalog, public
as $$
declare
  v_item record;
  v_on_hand numeric(14,3);
  v_claimed bigint;
  v_enforced boolean;
begin
  insert into public."OrderStockDeduction" ("OrderID") values (p_order_id)
  on conflict do nothing returning "OrderID" into v_claimed;
  if v_claimed is null then return; end if;

  select coalesce((select lower("SettingValue") = 'true' from public."ShopSetting" where "SettingKey" = 'inventory_enforced'), false)
    into v_enforced;
  if v_enforced and exists (
    select 1 from public."OrderItem" oi
    where oi."OrderID" = p_order_id
      and not exists (select 1 from public."MenuItemIngredient" recipe where recipe."MenuItemID" = oi."ItemID")
  ) then
    raise exception 'Inventory recipe is missing for a menu item on this ticket' using errcode = '23514';
  end if;

  for v_item in
    select recipe."InventoryItemID", sum(recipe."QuantityRequired" * oi."Quantity")::numeric(14,3) as quantity_needed
    from public."OrderItem" oi
    join public."MenuItemIngredient" recipe on recipe."MenuItemID" = oi."ItemID"
    join public."InventoryItem" inventory on inventory."InventoryItemID" = recipe."InventoryItemID"
    where oi."OrderID" = p_order_id
    group by recipe."InventoryItemID"
    order by recipe."InventoryItemID"
  loop
    select "QuantityOnHand" into v_on_hand
      from public."InventoryItem"
      where "InventoryItemID" = v_item."InventoryItemID" and "IsActive"
      for update;
    if not found or v_on_hand < v_item.quantity_needed then
      raise exception 'Insufficient stock for inventory item %', v_item."InventoryItemID" using errcode = '23514';
    end if;
    update public."InventoryItem"
      set "QuantityOnHand" = "QuantityOnHand" - v_item.quantity_needed,
          "UpdatedAt" = clock_timestamp()
      where "InventoryItemID" = v_item."InventoryItemID";
    insert into public."InventoryMovement" (
      "InventoryItemID", "QuantityChange", "Reason", "MovementType", "OrderID", "EmployeeID"
    ) values (
      v_item."InventoryItemID", -v_item.quantity_needed, 'Sale for ticket #' || p_order_id,
      'sale', p_order_id, p_employee_id
    );
  end loop;
end;
$$;
revoke all on function public.esmiringkape_deduct_order_stock(bigint, bigint) from public, anon, authenticated;

create or replace function public.esmiringkape_admin_inventory_list()
returns jsonb
language plpgsql
stable
security definer
set search_path = pg_catalog, public
as $$
begin
  if public.esmiringkape_staff_role() is distinct from 'admin' then
    raise exception 'Administrator access required' using errcode = '42501';
  end if;
  return coalesce((
    select jsonb_agg(to_jsonb(i) order by i."Name") from public."InventoryItem" i
  ), '[]'::jsonb);
end;
$$;

create or replace function public.esmiringkape_admin_adjust_inventory(
  p_inventory_item_id bigint,
  p_quantity_change numeric,
  p_movement_type text,
  p_reason text
)
returns jsonb
language plpgsql
security definer
set search_path = pg_catalog, public
as $$
declare
  v_employee_id bigint;
  v_item public."InventoryItem"%rowtype;
begin
  if public.esmiringkape_staff_role() is distinct from 'admin' then
    raise exception 'Administrator access required' using errcode = '42501';
  end if;
  if p_movement_type not in ('opening_balance', 'receipt', 'return', 'waste', 'adjustment') then
    raise exception 'Unsupported stock movement type' using errcode = '22023';
  end if;
  if p_quantity_change = 0 or nullif(trim(p_reason), '') is null then
    raise exception 'A non-zero quantity and reason are required' using errcode = '22023';
  end if;
  if (p_movement_type in ('opening_balance', 'receipt', 'return') and p_quantity_change < 0)
     or (p_movement_type = 'waste' and p_quantity_change > 0) then
    raise exception 'Receipt/return quantities must be positive and waste quantities must be negative' using errcode = '22023';
  end if;
  v_employee_id := public.esmiringkape_current_employee_id();
  select * into v_item from public."InventoryItem"
    where "InventoryItemID" = p_inventory_item_id for update;
  if not found then raise exception 'Inventory item not found' using errcode = 'P0002'; end if;
  if v_item."QuantityOnHand" + p_quantity_change < 0 then
    raise exception 'Stock cannot be negative' using errcode = '23514';
  end if;
  update public."InventoryItem"
    set "QuantityOnHand" = "QuantityOnHand" + p_quantity_change,
        "UpdatedAt" = clock_timestamp()
    where "InventoryItemID" = p_inventory_item_id returning * into v_item;
  insert into public."InventoryMovement" (
    "InventoryItemID", "QuantityChange", "Reason", "MovementType", "EmployeeID"
  ) values (p_inventory_item_id, p_quantity_change, trim(p_reason), p_movement_type, v_employee_id);
  return to_jsonb(v_item);
end;
$$;

alter table public."InventoryItem" enable row level security;
alter table public."MenuItemIngredient" enable row level security;
alter table public."InventoryMovement" enable row level security;
alter table public."OrderStockDeduction" enable row level security;
revoke all on public."InventoryItem", public."MenuItemIngredient", public."InventoryMovement", public."OrderStockDeduction" from anon, authenticated;
revoke all on function public.esmiringkape_admin_inventory_list() from public, anon;
revoke all on function public.esmiringkape_admin_adjust_inventory(bigint, numeric, text, text) from public, anon;
grant execute on function public.esmiringkape_admin_inventory_list() to authenticated;
grant execute on function public.esmiringkape_admin_adjust_inventory(bigint, numeric, text, text) to authenticated;

commit;

